// 1. Obtienes el objeto completo del nodo 'format-data'.
const inputJson = $('format-data').first().json;

// 2. Apuntamos al objeto correcto que contiene las banderas '10dias' y '30dias'.
const actionFlags = inputJson.action;

// Variable para almacenar el resultado final.
let actionResult = '';

// 3. Lógica que ya maneja true/"true" y false/"false" correctamente.
// Solo entra en los 'if' si el valor es explícitamente verdadero.
if (actionFlags['30dias'] === true || actionFlags['30dias'] === 'true') {
  actionResult = '30-dias-despues';
}
else if (actionFlags['10dias'] === true || actionFlags['10dias'] === 'true') {
  actionResult = '10-dias-despues';
}
// Si no es ninguno de los casos anteriores (incluyendo false y "false"), entra aquí.
else {
  actionResult = 'new';
}

// 4. Devolvemos el resultado final junto con las variables de depuración.
return [{
  json: {
    // El resultado principal y final de la operación
    action: actionResult
  }
}];
